mapper.select:


    inner join sys_user u on u.user_name = toutdeliverysamllrecord.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    toutdeliverysamllrecord.del_flag = '0'
     and toutdeliverysamllrecord.out_delivery_detail_id = #{outDeliveryDetailId}
     and toutdeliverysamllrecord.material_detail_id = #{materialDetailId}
     and toutdeliverysamllrecord.location_id = #{locationId}
     and toutdeliverysamllrecord.tray_id = #{trayId}


${params.dataScope}
